function mergeUniqueBy(baseList, extraList, keyFn, minCount) {
  const seen = new Set();
  const out = [];
  for (const item of [...(baseList || []), ...(extraList || [])]) {
    const k = keyFn(item);
    if (!k || seen.has(k)) continue;
    seen.add(k);
    out.push(item);
  }
  while (out.length < minCount && out.length > 0) {
    const base = out[out.length % Math.max(1, out.length)];
    out.push({ ...base });
  }
  return out;
}

